// ============ v4 Match SKUs & Build Rows ============
// Combines Shopify orders + Walkin CSV, applies filters, validations,
// dedupes against existing destination, emits rows to append.

// ----- helpers -----
function parsePrice(s) {
  if (s === undefined || s === null || s === '') return 0;
  const m = String(s).replace(/[$,\s]/g, '').match(/-?\d+(?:\.\d+)?/);
  return m ? parseFloat(m[0]) : 0;
}
function escRegex(s) { return s.replace(/[.+?^${}()|[\]\\]/g, '\\$&'); }
function fmtSGD(n) { return '$' + Number(n).toFixed(2); }
const MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const MON_NUM = {Jan:'01',Feb:'02',Mar:'03',Apr:'04',May:'05',Jun:'06',Jul:'07',Aug:'08',Sep:'09',Oct:'10',Nov:'11',Dec:'12'};
function fmtDate(d) { if (!d || isNaN(d.getTime())) return ''; return d.getDate() + ' ' + MON[d.getMonth()] + ' ' + d.getFullYear(); }
function parseDMmmYyyy(s) {
  const m = String(s || '').trim().match(/^(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d{4})$/);
  if (!m) return null;
  return new Date(m[3] + '-' + MON_NUM[m[2]] + '-' + m[1].padStart(2, '0') + 'T00:00:00+08:00');
}
function parseCsvLine(line) {
  const out = []; let cur = ''; let inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (inQ) {
      if (c === '"' && line[i+1] === '"') { cur += '"'; i++; }
      else if (c === '"') inQ = false;
      else cur += c;
    } else {
      if (c === ',') { out.push(cur); cur = ''; }
      else if (c === '"') inQ = true;
      else cur += c;
    }
  }
  out.push(cur);
  return out;
}

// ----- Amount Reference -----
const refRows = $('Read Amount Reference').all().map(it => it.json);
const masters = [];
for (const r of refRows) {
  const sku = String(r['SKU'] || '').trim();
  if (!sku) continue;
  const listing  = parsePrice(r['Listing Price']);
  const fee      = parsePrice(r['3DPS + Stripe Fee (3.4%)']);
  const takehome = parsePrice(r['Gavin Amount (Takehome)']);
  const pat = '^' + escRegex(sku).replace(/COLOUR|XXX/g, '.+') + '$';
  masters.push({ sku, listing, fee, takehome, re: new RegExp(pat, 'i') });
}
function findMaster(sku) {
  if (!sku) return null;
  for (const m of masters) if (m.re.test(sku)) return m;
  return null;
}

// ----- Exclusion regexes -----
const excludeStr = $('Set Parameters').first().json.EXCLUDE_SKUS || '';
const excludeRegexes = excludeStr.split(',').map(s => s.trim()).filter(Boolean).map(p =>
  new RegExp('^' + escRegex(p).replace(/\\\\\*/g, '.*') + '$', 'i')
);
function isExcluded(sku) { return sku && excludeRegexes.some(re => re.test(sku)); }
function titleHints(li) {
  const t = ((li.title || '') + ' ' + (li.variant_title || '')).toLowerCase();
  return t.includes('gfz') || t.includes('gavin') || t.includes('sbl') || t.includes('sbf');
}

// ----- Existing dest rows for dedup -----
const existingItems = $input.all();
const existingRows = existingItems.map(it => it.json).filter(r => r && Object.keys(r).length > 0);
const existingKeys = new Set();
for (const r of existingRows) {
  const k = String(r['Order No.'] || '').trim() + '|' + String(r['SKU'] || '').trim();
  if (k !== '|') existingKeys.add(k);
}
const isFirstRun = existingRows.length === 0;

// ----- Stats accumulator -----
const stats = {
  shopify_orders: 0,
  shopify_line_items: 0,
  rows_built: 0,
  duplicates_skipped: 0,
  flagged_currency: 0,
  flagged_refund: 0,
  flagged_underprice: 0,
  flagged_title_match: 0,
  walkin_rows_total: 0,
  walkin_rows_in_month: 0,
  walkin_deduped_against_shopify: 0,
};

// Track Shopify order numbers for Walkin dedup-merge (knowledge transfer rule: matches v5)
const shopifyOrderNoSet = new Set();

// ----- Shopify orders -----
const pages = $('Fetch All Orders (paginated)').all();
const orders = pages.flatMap(p => p.json.orders || []);
stats.shopify_orders = orders.length;

const monthStart = new Date($('Set Parameters').first().json.MONTH_START_ISO);
const monthEnd   = new Date($('Set Parameters').first().json.MONTH_END_ISO);

const outRows = [];
for (const o of orders) {
  for (const li of (o.line_items || [])) {
    stats.shopify_line_items++;
    if (isExcluded(li.sku)) continue;
    const master = findMaster(li.sku);
    const titleHit = !master && titleHints(li);
    if (!master && !titleHit) continue;

    const flags = [];
    const orderCcy = (o.currency || '').toUpperCase();
    if (orderCcy !== 'SGD') {
      flags.push('CURRENCY: ' + (o.currency || 'unknown'));
      stats.flagged_currency++;
    }
    if (Array.isArray(o.refunds) && o.refunds.length > 0) {
      flags.push('REFUND - verify');
      stats.flagged_refund++;
    }

    const firstName = (o.customer && o.customer.first_name) || '';
    const lastName  = (o.customer && o.customer.last_name)  || '';
    const name = (firstName + ' ' + lastName).trim() || 'Guest';
    const orderNo = o.order_number != null ? String(o.order_number) : String(o.name || '').replace('#','');
    shopifyOrderNoSet.add(orderNo);
    const dateFmt = fmtDate(new Date(o.created_at));
    const email   = o.email || '';
    const qty     = li.quantity || 1;

    const liShopPrice = li.price_set && li.price_set.shop_money
      ? parseFloat(li.price_set.shop_money.amount || 0)
      : parseFloat(li.price || 0);

    let listing, fee, takehome;
    if (master) {
      if (liShopPrice < master.listing - 0.01) {
        flags.push('UNDERPRICED: shopify=$' + liShopPrice.toFixed(2) + ' listed=$' + master.listing.toFixed(2));
        stats.flagged_underprice++;
        listing  = liShopPrice;
        fee      = master.fee;
        takehome = liShopPrice - master.fee;
      } else {
        listing  = master.listing;
        fee      = master.fee;
        takehome = master.takehome;
      }
    } else {
      flags.push('TITLE MATCH - add to Amount Reference?');
      stats.flagged_title_match++;
      listing  = liShopPrice;
      fee      = null;
      takehome = null;
    }

    // Emit qty rows (one per unit)
    for (let i = 0; i < qty; i++) {
      const key = orderNo + '|' + (li.sku || '');
      if (existingKeys.has(key)) { stats.duplicates_skipped++; continue; }
      outRows.push({
        'Order No.':                orderNo,
        'Date':                     dateFmt,
        'Name':                     name,
        'Email':                    email,
        'Gdrive access':            '',
        'SKU':                      li.sku || '',
        'Listing Price':            fmtSGD(listing),
        '3DPS+Stripe Fee':          fee !== null ? fmtSGD(fee) : '',
        'Gavin Amount (Takehome)':  takehome !== null ? fmtSGD(takehome) : '',
        'Payment Complete':         '',
        'Date of Payment':          '',
        'Remarks':                  flags.join(' | '),
      });
      stats.rows_built++;
    }
  }
}

// ----- Walkin source (n8n Sheets node, one tab per month) -----
const walkinItems = $('Read Walkin Source').all().map(it => it.json).filter(j => j && Object.keys(j).length > 0);
function wf(r, names) {
  for (const n of names) if (r[n] !== undefined && r[n] !== null && r[n] !== '') return r[n];
  return '';
}
function toSgdStr(v) {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'number') return '$' + v.toFixed(2);
  const s = String(v).trim();
  if (s.startsWith('$') || s.startsWith('-$')) return s;
  if (/^-?\d+(\.\d+)?$/.test(s)) return '$' + parseFloat(s).toFixed(2);
  return s;
}
for (const r of walkinItems) {
  stats.walkin_rows_total++;
  const dateStr = String(wf(r, ['Date']) || '').trim();
  const dateObj = parseDMmmYyyy(dateStr);
  if (!dateObj) continue;
  if (dateObj < monthStart || dateObj > monthEnd) continue;
  stats.walkin_rows_in_month++;
  const orderNo = String(wf(r, ['OrderNo.', 'Order No.', 'OrderNo'])).trim();
  const sku     = String(wf(r, ['SKU'])).trim();
  if (orderNo && shopifyOrderNoSet.has(orderNo)) { stats.walkin_deduped_against_shopify++; continue; }
  const key     = orderNo + '|' + sku;
  if (existingKeys.has(key)) { stats.duplicates_skipped++; continue; }
  outRows.push({
    'Order No.':                orderNo,
    'Date':                     dateStr,
    'Name':                     String(wf(r, ['Name'])),
    'Email':                    String(wf(r, ['Email'])),
    'Gdrive access':            String(wf(r, ['Gdrive access'])),
    'SKU':                      sku,
    'Listing Price':            toSgdStr(wf(r, ['Listing Price'])),
    '3DPS+Stripe Fee':          toSgdStr(wf(r, ['3DPS + Stripe Fee (3.4%)', '3DPS+Stripe Fee', '3DPS + Stripe Fee'])),
    'Gavin Amount (Takehome)':  toSgdStr(wf(r, ['Gavin Amount (Takehome)'])),
    'Payment Complete':         String(wf(r, ['Payment Complete'])),
    'Date of Payment':          String(wf(r, ['Date of Payment'])),
    'Remarks':                  String(wf(r, ['Remarks'])),
  });
  stats.rows_built++;
}

// ----- Sort combined rows by Date ascending so Walkin interleaves with Shopify by date -----
function dateKey(s) {
  const d = parseDMmmYyyy(s);
  return d ? d.getTime() : 0;
}
outRows.sort((a, b) => dateKey(a['Date']) - dateKey(b['Date']));

// ----- Return clean data rows. autoMap append seeds row 1 headers from keys. -----
return outRows.map(r => ({ json: r }));

// Derive stats from raw sources + Match output.
const matchItems = $('Match SKUs & Build Rows').all().map(it => it.json).filter(j => j && j['Order No.'] !== undefined);
const orders = $('Fetch All Orders (paginated)').all().flatMap(p => p.json.orders || []);
const shopifyLineItems = orders.reduce((acc, o) => acc + ((o.line_items || []).length), 0);

const walkinTotal = $('Read Walkin Source').all().filter(it => it.json && Object.keys(it.json).length > 0).length;

function countFlag(needle) {
  return matchItems.filter(r => (r['Remarks'] || '').includes(needle)).length;
}

const params = $('Set Parameters').first().json;
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const tsStr = now.getFullYear() + '-' + pad(now.getMonth()+1) + '-' + pad(now.getDate()) +
              ' ' + pad(now.getHours()) + ':' + pad(now.getMinutes()) + ':' + pad(now.getSeconds());

// walkin_in_month: count of rows in matchItems whose Order No. == 'Walkin'
const walkinInMonth = matchItems.filter(r => String(r['Order No.'] || '').toLowerCase() === 'walkin').length;

return [{ json: {
  'timestamp':              tsStr,
  'tab':                    params.TAB_NAME,
  'shopify_orders':         orders.length,
  'shopify_line_items':     shopifyLineItems,
  'walkin_total':           walkinTotal,
  'walkin_in_month':        walkinInMonth,
  'new_rows':               matchItems.length,
  'flagged_currency':       countFlag('CURRENCY'),
  'flagged_refund':         countFlag('REFUND'),
  'flagged_underprice':     countFlag('UNDERPRICED'),
  'flagged_title_match':    countFlag('TITLE MATCH'),
  'status':                 'success'
}}];

